do $do$
declare run_id bigint; rid bigint; a bigint; b bigint; r record; k int;
begin
insert into public.companies(name,entity_type) select v.n,v.t from (values ($q$ASML$q$,$q$public_company$q$),($q$Altera$q$,$q$private_company$q$),($q$Broadcom$q$,$q$public_company$q$),($q$GlobalFoundries$q$,$q$public_company$q$),($q$IMS Nanofabrication$q$,$q$private_company$q$),($q$MediaTek$q$,$q$public_company$q$),($q$Meta$q$,$q$public_company$q$),($q$Mobileye$q$,$q$public_company$q$),($q$Qualcomm$q$,$q$public_company$q$),($q$SMIC$q$,$q$public_company$q$),($q$Samsung$q$,$q$public_company$q$),($q$SoftBank Group$q$,$q$public_company$q$),($q$U.S. Department of Commerce$q$,$q$institution$q$),($q$U.S. government$q$,$q$institution$q$),($q$UMC$q$,$q$public_company$q$)) v(n,t) where not exists (select 1 from public.companies c where lower(c.name)=lower(v.n));
create temp table _q(i int primary key, t text) on commit drop;
insert into _q values (1,$q$As of December 27, 2025, we continued to consolidate Mobileye and held equity interests representing an 80% ownership interest in Mobileye;$q$),(2,$q$As of and after September 12, 2025, our retained non-marketable equity interest in Altera is accounted for as an equity method investment.$q$),(3,$q$As we pursue our strategy to establish Intel Foundry as a major provider of foundry capacity to manufacture semiconductors for others, we face intense competition from well-established competitors such as TSMC, Samsung, Global Foundries, UMC and SMIC.$q$),(4,$q$CCG's primary competitor is AMD, which like us designs processors based on the x86 architecture.$q$),(5,$q$DCAI competitors include AMD, which utilizes the x86 architecture and competes with us across the full spectrum of CPUs, GPUs, accelerators and other products; providers of GPU systems such as NVIDIA, whose GPU systems have experienced the highest demand in the market as AI workloads have become the dominant source of compute demand; companies developing their own custom silicon, including many hyperscalers such as Amazon, Google, Meta and Microsoft; and both new entrants and incumbents developing ARM- and RISC-V-based products tailored to specific data center and AI workloads.$q$),(6,$q$Effective September 12, 2025, Altera, previously a wholly-owned subsidiary, was deconsolidated from our Consolidated Financial Statements following the closing of the sale of 51% of Altera's issued and outstanding common stock.$q$),(7,$q$For example, ASML Holding N.V. (ASML) is currently the sole supplier of EUV lithography tools that we are deploying in our Intel 4, Intel 3, Intel 18A and planned future leading-edge manufacturing process nodes.$q$),(8,$q$For example, in 2020, Apple introduced PC products utilizing its own internally developed ARM-based semiconductor designs in place of our client CPUs, and we face increasing competition from Apple's products and ecosystem.$q$),(9,$q$In 2024, we announced a strategic collaboration with UMC to develop a 12 nm process platform that expands our mature‑node process portfolio and strengthens our U.S.-based manufacturing foundry capabilities, with production expected to begin in 2027.$q$),(10,$q$In some cases, however, we are reliant upon sole-source providers, such as with the EUV lithography tools manufactured by ASML that are required for leading-edge process technologies, or providers that are substantially concentrated in a single country, such as with certain rare earth minerals critical to the functioning of a range of technology products and processes where China is the primary source of global supply.$q$),(11,$q$Other Intel Foundry competitors include GlobalFoundries, UMC and SMIC, which primarily focus on mature process technologies.$q$),(12,$q$Our competitors include companies offering platform products, such as AMD and Qualcomm; accelerator products such as GPUs, including those offered by NVIDIA and AMD; other accelerator products such as ASICs, application-specific standard products and FPGAs; memory and storage products; connectivity and networking products; and other semiconductor products.$q$),(13,$q$Our primary competitor in leading-edge semiconductor process technology is TSMC, which holds a leading position in manufacturing at scale for the most advanced nodes.$q$),(14,$q$Some of our most advanced current and future products are or will be either exclusively manufactured by TSMC or reliant upon critical components, including various compute die, manufactured by TSMC.$q$),(15,$q$The transactions resulted in the U.S. government becoming one of our largest stockholders.$q$),(16,$q$Upon closing the transaction, we deconsolidated Altera from our Consolidated Financial Statements and retained a 49% minority investment in Altera which we accounted for under the equity method of accounting.$q$),(17,$q$We also announced a strategic partnership with NVIDIA to co-develop custom client and data center products combining our x86 CPU technologies with NVIDIA's AI and accelerated computing capabilities.$q$),(18,$q$We also compete directly with Samsung in this market.$q$),(19,$q$We also compete with Broadcom in the custom ASICs development market.$q$),(20,$q$We also face significant competition from companies that design processors based on the ARM architecture, such as Apple with its M series products, Qualcomm with its Snapdragon products and MediaTek with its Kompanio products.$q$),(21,$q$We consolidate our majority owned subsidiary Mobileye pursuant to the voting interest model.$q$),(22,$q$We continue to consolidate IMS results as a majority owned subsidiary pursuant to the voting interest model into our Consolidated Financial Statements.$q$),(23,$q$We expect to continue to use TSMC and other third-party foundry suppliers for various key tiles in a number of current and future products.$q$),(24,$q$We provide semiconductor wafer manufacturing services to Altera, a related party, in accordance with a wafer manufacturing and sale agreement.$q$),(25,$q$on August 18, 2025, we entered into an agreement with SoftBank Group to issue and sell to SoftBank Group 87 million shares of our common stock at $23.00 per share, representing an aggregate cash purchase price of $2.0 billion.$q$),(26,$q$on September 15, 2025, we entered into an agreement with NVIDIA to issue and sell to NVIDIA 215 million shares of our common stock at $23.28 per share for an aggregate cash purchase price of $5.0 billion.$q$),(27,$q$we issued to the DOC 275 million shares of our common stock and a warrant to purchase up to 241 million shares of our common stock at $20.00 per share if we were to cease to directly or indirectly own at least 51% of our Intel Foundry business$q$);
create temp table _e(n int, ty text, s text, g text, qs int[], sec text[], pct numeric, qual text, basis text, note text) on commit drop;
insert into _e values (1,$q$partners$q$,$q$INTC$q$,$q$NVIDIA$q$,$q${17}$q$::int[],$q${notes}$q$::text[],null,null,null,null),(2,$q$partners$q$,$q$INTC$q$,$q$UMC$q$,$q${9}$q$::int[],$q${notes}$q$::text[],null,null,null,null),(3,$q$competes$q$,$q$INTC$q$,$q$AMD$q$,$q${4,5,12}$q$::int[],$q${notes,notes,notes}$q$::text[],null,null,null,null),(4,$q$competes$q$,$q$INTC$q$,$q$Apple$q$,$q${20,8}$q$::int[],$q${notes,notes}$q$::text[],null,null,null,null),(5,$q$competes$q$,$q$INTC$q$,$q$Qualcomm$q$,$q${20,12}$q$::int[],$q${notes,notes}$q$::text[],null,null,null,null),(6,$q$competes$q$,$q$INTC$q$,$q$MediaTek$q$,$q${20}$q$::int[],$q${notes}$q$::text[],null,null,null,null),(7,$q$competes$q$,$q$INTC$q$,$q$NVIDIA$q$,$q${5,12}$q$::int[],$q${notes,notes}$q$::text[],null,null,null,null),(8,$q$competes$q$,$q$INTC$q$,$q$Amazon$q$,$q${5}$q$::int[],$q${notes}$q$::text[],null,null,null,null),(9,$q$competes$q$,$q$INTC$q$,$q$Alphabet$q$,$q${5}$q$::int[],$q${notes}$q$::text[],null,null,null,null),(10,$q$competes$q$,$q$INTC$q$,$q$Meta$q$,$q${5}$q$::int[],$q${notes}$q$::text[],null,null,null,null),(11,$q$competes$q$,$q$INTC$q$,$q$Microsoft$q$,$q${5}$q$::int[],$q${notes}$q$::text[],null,null,null,null),(12,$q$competes$q$,$q$INTC$q$,$q$Broadcom$q$,$q${19}$q$::int[],$q${notes}$q$::text[],null,null,null,null),(13,$q$competes$q$,$q$INTC$q$,$q$TSMC$q$,$q${13,3}$q$::int[],$q${notes,notes}$q$::text[],null,null,null,null),(14,$q$competes$q$,$q$INTC$q$,$q$Samsung$q$,$q${18,3}$q$::int[],$q${notes,notes}$q$::text[],null,null,null,null),(15,$q$competes$q$,$q$INTC$q$,$q$GlobalFoundries$q$,$q${11,3}$q$::int[],$q${notes,notes}$q$::text[],null,null,null,null),(16,$q$competes$q$,$q$INTC$q$,$q$UMC$q$,$q${11,3}$q$::int[],$q${notes,notes}$q$::text[],null,null,null,null),(17,$q$competes$q$,$q$INTC$q$,$q$SMIC$q$,$q${11,3}$q$::int[],$q${notes,notes}$q$::text[],null,null,null,null),(18,$q$supplies$q$,$q$TSMC$q$,$q$INTC$q$,$q${23,14}$q$::int[],$q${notes,notes}$q$::text[],null,null,null,null),(19,$q$supplies$q$,$q$ASML$q$,$q$INTC$q$,$q${10,7}$q$::int[],$q${notes,notes}$q$::text[],null,null,null,null),(20,$q$invests$q$,$q$INTC$q$,$q$Mobileye$q$,$q${1,21}$q$::int[],$q${notes,notes}$q$::text[],80,$q$exact$q$,$q$source_revenue$q$,null),(21,$q$invests$q$,$q$INTC$q$,$q$Altera$q$,$q${2,16,6}$q$::int[],$q${notes,notes,notes}$q$::text[],null,null,null,null),(22,$q$invests$q$,$q$U.S. Department of Commerce$q$,$q$INTC$q$,$q${27}$q$::int[],$q${notes}$q$::text[],null,null,null,null),(23,$q$invests$q$,$q$SoftBank Group$q$,$q$INTC$q$,$q${25}$q$::int[],$q${notes}$q$::text[],null,null,null,null),(24,$q$invests$q$,$q$NVIDIA$q$,$q$INTC$q$,$q${26}$q$::int[],$q${notes}$q$::text[],null,null,null,null),(25,$q$invests$q$,$q$U.S. government$q$,$q$INTC$q$,$q${15}$q$::int[],$q${notes}$q$::text[],null,null,null,null),(26,$q$sells_to$q$,$q$INTC$q$,$q$Altera$q$,$q${24}$q$::int[],$q${notes}$q$::text[],null,null,null,null),(27,$q$invests$q$,$q$INTC$q$,$q$IMS Nanofabrication$q$,$q${22}$q$::int[],$q${notes}$q$::text[],null,null,null,null);
create or replace function pg_temp.nid(l text) returns bigint language sql as $f$ select id from public.companies where case l when $q$Amazon$q$ then ticker=$q$AMZN$q$ when $q$Alphabet$q$ then ticker=$q$GOOGL$q$ when $q$Microsoft$q$ then ticker=$q$MSFT$q$ when $q$NVIDIA$q$ then ticker=$q$NVDA$q$ when $q$AMD$q$ then ticker=$q$AMD$q$ when $q$TSMC$q$ then ticker=$q$TSM$q$ when $q$Apple$q$ then ticker=$q$AAPL$q$ when $q$INTC$q$ then ticker=$q$INTC$q$ else lower(name)=lower(l) end order by id limit 1 $f$;
insert into public.agent_runs(agent_name,mode,target,model,tokens_in,tokens_out,cost_usd,status,review_status) values ('filings_extraction','batch',$q$INTC M6 group 2-4$q$,'claude-sonnet-5-5',262549,10979,0.8835,'completed','unreviewed') returning id into run_id;
for r in select * from _e order by n loop a := pg_temp.nid(r.s); b := pg_temp.nid(r.g); if r.ty in ('competes','partners') and a > b then rid := a; a := b; b := rid; end if; rid := null; select id into rid from public.relationships where source_id=a and target_id=b and relationship_type=r.ty order by id limit 1; if rid is null then insert into public.relationships(source_id,target_id,relationship_type,exposure_pct,exposure_qualifier,exposure_basis,exposure_as_of,source_type,status,run_id,as_of_date,note) values (a,b,r.ty,r.pct,r.qual,case when r.pct is null then 'none' else r.basis end,case when r.pct is null then null else '2025-12-31'::date end,'sec_filing','staged',run_id,'2025-12-31',r.note) returning id into rid; end if; if (select status from public.relationships where id=rid)='staged' then for k in 1..array_length(r.qs,1) loop insert into public.evidence(relationship_id,document_url,section,quote,quote_found,published_at) select rid,$q$https://www.sec.gov/Archives/edgar/data/50863/000005086326000011/intc-20251227.htm$q$,r.sec[k],t,true,$q$2026-01-23$q$ from _q where i=r.qs[k]; end loop; end if; end loop;
end $do$;
